repository.template:
import { D1Database } from '@cloudflare/workers-types';
import { Create{Model}Dto, Update{Model}Dto, {Model} } from '@/types/{model}.types';
import { RepositoryError } from '@/lib/errors';

export class {Model}Repository {
  constructor(private db: D1Database) {}

  async create(data: Create{Model}Dto): Promise<{Model}> {
    try {
      const stmt = this.db.prepare(`
        INSERT INTO {table_name} ({columns})
        VALUES ({values})
        RETURNING *
      `);

      const result = await stmt.bind(...Object.values(data)).first();
      return result as {Model};
    } catch (error) {
      throw new RepositoryError('Failed to create {model}', error);
    }
  }

  async findById(id: string): Promise<{Model} | null> {
    try {
      const result = await this.db
        .prepare(`SELECT * FROM {table_name} WHERE id = ?`)
        .bind(id)
        .first();
      return result as {Model} | null;
    } catch (error) {
      throw new RepositoryError('Failed to find {model} by id', error);
    }
  }

  async findAll(filters?: Partial<{Model}>): Promise<{Model}[]> {
    try {
      let query = 'SELECT * FROM {table_name}';
      const params: any[] = [];

      if (filters && Object.keys(filters).length > 0) {
        const conditions = Object.keys(filters).map(key => `${key} = ?`);
        query += ' WHERE ' + conditions.join(' AND ');
        params.push(...Object.values(filters));
      }

      const result = await this.db.prepare(query).bind(...params).all();
      return result.results as {Model}[];
    } catch (error) {
      throw new RepositoryError('Failed to find all {models}', error);
    }
  }

  async update(id: string, data: Update{Model}Dto): Promise<{Model}> {
    try {
      const setClause = Object.keys(data).map(key => `${key} = ?`).join(', ');
      const stmt = this.db.prepare(`
        UPDATE {table_name} 
        SET ${setClause}
        WHERE id = ?
        RETURNING *
      `);

      const result = await stmt.bind(...Object.values(data), id).first();
      return result as {Model};
    } catch (error) {
      throw new RepositoryError('Failed to update {model}', error);
    }
  }

  async delete(id: string): Promise<boolean> {
    try {
      const result = await this.db
        .prepare(`DELETE FROM {table_name} WHERE id = ?`)
        .bind(id)
        .run();
      return result.changes > 0;
    } catch (error) {
      throw new RepositoryError('Failed to delete {model}', error);
    }
  }
}

